'use server'

import { updateTag } from 'next/cache'
import { createPostRecord } from './lib/posts'

export async function createPost(formData: FormData): Promise<void> {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || !title.trim()) {
    throw new Error('A post title is required.')
  }

  if (typeof content !== 'string') {
    throw new Error('Post content must be text.')
  }

  await createPostRecord({
    title: title.trim(),
    content: content.trim(),
  })

  updateTag('posts')
}
export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

type PostStore = typeof globalThis & {
  posts?: Post[]
}

function getPostStore(): Post[] {
  const store = globalThis as PostStore
  store.posts ??= []
  return store.posts
}

export async function createPostRecord(input: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }

  getPostStore().unshift(post)
  return post
}

export async function getPosts(): Promise<Post[]> {
  return getPostStore()
